# cc-proxy

Local Anthropic proxy for Claude Code: model aliases (haiku/sonnet/opus/fable) go to other providers'
Anthropic-compatible endpoints with fallbacks, ending at Claude. Guide and measured facts:
`~/chat/docs/agent/261111-claude-code-proxy-opencode-go-xai.md`.

- Pure logic lives in `config.ts`, `normalize.ts`, `stats.ts` (`bun test`); `server.ts` is I/O.
- One request transform for every non-Anthropic provider (strictest wins); provider differences are only
  URL, auth and extra headers in `upstreams.ts`. Do not branch routing on a provider name.
- Credentials come from pi's `~/.pi/agent/auth.json`; OAuth refresh takes pi's `auth.json.lock`.
- Consumers: Claude Code plugin `~/.agents/plugins/proxy`, dashboard `apps/server/src/cc_proxy.rs` +
  `apps/client/src/lib/settings/cc-proxy-section.svelte`. Keep `/_proxy/*` shapes in step with them.
- After a change: `bun test`, `bunx tsc -p .`, `systemctl --user restart cc-proxy`, then
  `claude -p "say: pong" --model haiku </dev/null` and `cc-proxy status`.
====CONFIG
/**
 * cc-proxy 설정 — `~/.config/cc-proxy/config.json`.
 *
 * Claude Code 별칭(haiku/sonnet/opus/fable)마다 프록시 대상 체인을 둔다. 체인 앞에서부터 시도하고,
 * 모두 실패하면 원래 Claude 모델(Anthropic 직행)로 간다. 체인이 비면 그 별칭은 그대로 Anthropic이다.
 * `enabled: false`면 모든 요청이 그대로 Anthropic으로 간다(Claude Code는 세션 중에도 프록시를 거친다).
 */
import { existsSync, mkdirSync, readFileSync, renameSync, statSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { homedir } from "node:os";

export const ALIASES = ["haiku", "sonnet", "opus", "fable"] as const;
export type Alias = (typeof ALIASES)[number];
export const EFFORTS = ["low", "medium", "high", "xhigh", "max"] as const;
export type Effort = (typeof EFFORTS)[number];

/** 체인 한 칸: `provider/model`. `effort`가 있으면 Claude Code가 보낸 effort 대신 이 값을 보낸다. */
export type Target = { model: string; effort?: Effort };
export type Route = { chain: Target[] };
export type Config = {
	enabled: boolean;
	routes: Record<Alias, Route>;
	/** 429·5xx·연결·인증 실패 뒤 그 대상을 건너뛰는 시간. */
	cooldownSeconds: number;
};

export const PORT = Number(process.env.CC_PROXY_PORT ?? 45870);

export const DEFAULT_CONFIG: Config = {
	enabled: true,
	routes: {
		haiku: { chain: [{ model: "opencode-go/deepseek-v4.1-flash" }] },
		sonnet: { chain: [{ model: "xai/grok-4.7" }] },
		opus: { chain: [] },
		fable: { chain: [] },
	},
	cooldownSeconds: 60,
};

export function configDir(): string {
	return process.env.CC_PROXY_CONFIG_DIR ?? join(homedir(), ".config", "cc-proxy");
}

/** Claude 모델 ID(`claude-haiku-5-5`, `claude-opus-5-5[1m]`)의 별칭. Claude가 아니면 null. */
export function aliasOf(model: unknown): Alias | null {
	if (typeof model !== "string") return null;
	const match = /^claude-(haiku|sonnet|opus|fable)\b/.exec(model.toLowerCase());
	return (match?.[1] as Alias | undefined) ?? null;
}

/** `provider/model` → 둘로. 형식이 틀리면 null. */
export function splitTarget(model: string): { provider: string; id: string } | null {
	const slash = model.indexOf("/");
	if (slash <= 0 || slash === model.length - 1) return null;
	return { provider: model.slice(0, slash), id: model.slice(slash + 1) };
}

/** 검증하고 빠진 칸은 기본값으로 채운다. 틀리면 이유를 던진다. */
export function validate(input: unknown, providers: readonly string[]): Config {
	if (!input || typeof input !== "object") throw new Error("config must be an object");
	const raw = input as Partial<Config> & { routes?: Partial<Record<string, Partial<Route>>> };
	const routes = {} as Record<Alias, Route>;
	for (const alias of ALIASES) {
		const chain = raw.routes?.[alias]?.chain ?? DEFAULT_CONFIG.routes[alias].chain;
		if (!Array.isArray(chain)) throw new Error(`${alias}: chain must be a list`);
		if (chain.length > 8) throw new Error(`${alias}: at most 8 targets`);
		const seen = new Set<string>();
		routes[alias] = {
			chain: chain.map((target) => {
				if (!target || typeof target.model !== "string") throw new Error(`${alias}: target needs a model`);
				const split = splitTarget(target.model);
				if (!split) throw new Error(`${alias}: ${target.model} is not provider/model`);
				if (!providers.includes(split.provider)) {
					throw new Error(`${alias}: provider ${split.provider} is not supported (${providers.join(", ")})`);
				}
				if (seen.has(target.model)) throw new Error(`${alias}: ${target.model} is listed twice`);
				seen.add(target.model);
				if (target.effort !== undefined && !EFFORTS.includes(target.effort)) {
					throw new Error(`${alias}: effort is ${EFFORTS.join("/")}`);
				}
				return target.effort ? { model: target.model, effort: target.effort } : { model: target.model };
			}),
		};
	}
	const cooldownSeconds = raw.cooldownSeconds ?? DEFAULT_CONFIG.cooldownSeconds;
	if (!(Number.isFinite(cooldownSeconds) && cooldownSeconds >= 0 && cooldownSeconds <= 3600)) {
		throw new Error("cooldownSeconds is 0–3600");
	}
	return { enabled: raw.enabled ?? DEFAULT_CONFIG.enabled, routes, cooldownSeconds };
}

/** 파일 버전: 저장할 때 읽은 버전과 다르면(그 사이 손으로 고쳤으면) 거절한다. */
export function versionOf(path: string): string {
	try {
		const stat = statSync(path);
		return `${stat.mtimeMs}-${stat.size}`;
	} catch {
		return "missing";
	}
}

export function configPath(): string {
	return join(configDir(), "config.json");
}

export function readConfig(providers: readonly string[]): { config: Config; version: string; error?: string } {
	const path = configPath();
	const version = versionOf(path);
	if (!existsSync(path)) return { config: DEFAULT_CONFIG, version };
	try {
		return { config: validate(JSON.parse(readFileSync(path, "utf8")), providers), version };
	} catch (cause) {
		return { config: DEFAULT_CONFIG, version, error: cause instanceof Error ? cause.message : String(cause) };
	}
}

export function writeConfig(config: Config): string {
	const path = configPath();
	mkdirSync(dirname(path), { recursive: true });
	const tmp = `${path}.${process.pid}.tmp`;
	writeFileSync(tmp, `${JSON.stringify(config, null, "\t")}\n`);
	renameSync(tmp, path);
	return versionOf(path);
}
====NORMALIZE
/**
 * 요청·응답 변환 — 순수 함수만.
 *
 * Claude Code는 Anthropic 전용 beta 형태를 보낸다: 대화 중간의 `role: "system"` 메시지,
 * `tool_addition` 블록(대화 중 추가된 도구), `tool_use.caller`, `context_management`,
 * `metadata.user_id`(계정 UUID). Anthropic 호환이라도 다른 업체는 이것을 422로 거절하므로
 * (xAI 실측 261111), 다른 업체로 보낼 때는 표준 Messages 형태로 바꾼다. 업체별로 갈래를 두지 않고
 * 가장 엄격한 쪽에 맞춘 한 가지 변환을 모두에 쓴다.
 *
 * thinking 블록의 서명은 업체마다 다르고 서로 검증하지 못한다. 그래서 다른 업체가 만든 thinking의
 * 서명 앞에 `ccproxy:<provider>:`를 붙여 두고, 다음 요청에서 그 업체로 갈 때만 원래 서명으로
 * 되돌려 남기고 나머지 대상(Anthropic 포함)에게서는 그 블록을 뺀다.
 */
import type { Effort } from "./config.ts";

type Json = Record<string, unknown>;
type Block = Json & { type?: string };
type Message = { role: string; content: string | Block[] };

export const TAG = "ccproxy:";
const tagOf = (provider: string) => `${TAG}${provider}:`;

const KNOWN_BLOCKS = new Set(["text", "image", "document", "tool_use", "tool_result", "thinking", "redacted_thinking"]);
const TOOL_KEYS = ["name", "description", "input_schema"] as const;

/** 엄격한 백엔드가 거절하는 키워드. 인자 검증은 Claude Code의 도구가 실행할 때 다시 한다. */
const DROPPED_SCHEMA_KEYS = new Set(["$schema", "pattern", "patternProperties", "propertyNames"]);

/**
 * JSON Schema를 가장 엄격한 업체에 맞춘다(261111 실측):
 * - null 값 키를 지운다. `properties`가 있는 객체에 `required`가 없으면 `[]`를 채운다
 *   (xAI는 빠진 `required`를 null로 읽어 422).
 * - `pattern`(제어 문자 `\0` 포함)·`propertyNames`·`$schema`를 지우고 `const`는 `enum`으로 바꾼다
 *   (OpenCode Go deepseek은 요청을 나눠 받는 백엔드 일부가 "invalid JSON Schema"로 400).
 * 스키마 자체가 아닌 곳(`properties`의 이름들, `enum` 값)은 키워드로 보지 않는다.
 */
export function strictSchema(value: unknown): unknown {
	if (Array.isArray(value)) return value.map(strictSchema);
	if (!value || typeof value !== "object") return value;
	const out: Json = {};
	for (const [key, inner] of Object.entries(value)) {
		if (inner === null || DROPPED_SCHEMA_KEYS.has(key)) continue;
		if (key === "const") out.enum = [inner];
		else if ((key === "properties" || key === "$defs" || key === "definitions") && typeof inner === "object") {
			out[key] = Object.fromEntries(Object.entries(inner as Json).map(([name, schema]) => [name, strictSchema(schema)]));
		} else if (key === "enum" || key === "default" || key === "examples" || key === "required") out[key] = inner;
		else out[key] = strictSchema(inner);
	}
	if (out.properties && typeof out.properties === "object" && !Array.isArray(out.required)) out.required = [];
	return out;
}

function blocks(content: Message["content"]): Block[] {
	return typeof content === "string" ? [{ type: "text", text: content }] : content;
}

/** cache_control은 남기되 Anthropic 전용 `ttl`은 뺀다. */
function plainCache(block: Block): Block {
	const out: Block = { ...block };
	const cache = out.cache_control as Json | undefined;
	if (cache && typeof cache === "object") out.cache_control = { type: "ephemeral" };
	return out;
}

/** 이 대상(`native`면 Anthropic)이 받을 thinking 블록만 남긴다. */
export function keepThinking(block: Block, target: string | "native"): Block | null {
	if (block.type === "redacted_thinking") return target === "native" ? block : null;
	if (block.type !== "thinking") return block;
	const signature = typeof block.signature === "string" ? block.signature : "";
	if (target === "native") return signature.startsWith(TAG) ? null : block;
	const tag = tagOf(target);
	if (!signature.startsWith(tag)) return null;
	return { ...block, signature: signature.slice(tag.length) };
}

/** 같은 역할이 이어지면 한 메시지로 합친다(블록을 지우고 나면 생길 수 있다). 빈 메시지는 뺀다. */
function mergeRuns(messages: Message[]): Message[] {
	const out: Message[] = [];
	for (const message of messages) {
		const content = blocks(message.content);
		if (content.length === 0) continue;
		const last = out.at(-1);
		if (last && last.role === message.role) last.content = [...blocks(last.content), ...content];
		else out.push({ role: message.role, content: [...content] });
	}
	return out;
}

/** Anthropic 직행 요청: 다른 업체가 만든 thinking 블록만 뺀다. 나머지는 손대지 않는다. */
export function forNative(body: Json): Json {
	const messages = body.messages as Message[] | undefined;
	if (!Array.isArray(messages)) return body;
	let touched = false;
	const next = messages.map((message) => {
		if (typeof message.content === "string") return message;
		const content = message.content.map((block) => keepThinking(block, "native")).filter((b): b is Block => b !== null);
		if (content.length !== message.content.length) touched = true;
		return { ...message, content };
	});
	return touched ? { ...body, messages: mergeRuns(next) } : body;
}

/** 다른 업체용 표준 Messages 요청. `provider`는 thinking 서명 태그, `model`은 업체 쪽 ID. */
export function forForeign(body: Json, provider: string, model: string, effort?: Effort): Json {
	const tools: Block[] = [];
	const toolNames = new Set<string>();
	const addTool = (tool: unknown) => {
		if (!tool || typeof tool !== "object") return;
		const source = tool as Json;
		// 서버 도구(web_search 등 type이 있는 것)는 그 업체에 없다.
		if (typeof source.type === "string" && source.type !== "custom") return;
		if (typeof source.name !== "string" || toolNames.has(source.name)) return;
		toolNames.add(source.name);
		const out: Block = {};
		for (const key of TOOL_KEYS) if (source[key] !== undefined) out[key] = source[key];
		out.input_schema = out.input_schema ? strictSchema(out.input_schema) : { type: "object", properties: {} };
		tools.push(out);
	};
	for (const tool of (body.tools as unknown[] | undefined) ?? []) addTool(tool);

	// 대화 중간 system 메시지: 텍스트는 앞(없으면 다음) user 메시지 끝에 붙인다.
	const messages: Message[] = [];
	let pending: Block[] = [];
	for (const message of (body.messages as Message[] | undefined) ?? []) {
		const content: Block[] = [];
		for (const raw of blocks(message.content)) {
			if (raw.type === "tool_addition") {
				addTool(raw.tool);
				continue;
			}
			const block = keepThinking(raw, provider);
			if (!block || !KNOWN_BLOCKS.has(String(block.type))) continue;
			const clean = plainCache(block);
			if (clean.type === "tool_use") delete clean.caller;
			if (clean.type === "thinking") delete clean.display;
			if (clean.type === "tool_result" && Array.isArray(clean.content)) {
				clean.content = (clean.content as Block[])
					.filter((part) => part.type === "text" || part.type === "image")
					.map(plainCache);
			}
			content.push(clean);
		}
		if (message.role === "system") {
			const text = content.filter((block) => block.type === "text");
			const previous = messages.at(-1);
			if (previous?.role === "user") previous.content = [...blocks(previous.content), ...text];
			else pending.push(...text);
			continue;
		}
		if (message.role === "user" && pending.length > 0) {
			content.push(...pending);
			pending = [];
		}
		messages.push({ role: message.role, content });
	}
	if (pending.length > 0) messages.push({ role: "user", content: pending });

	const out: Json = { model, messages: mergeRuns(messages), max_tokens: body.max_tokens ?? 32000 };
	for (const key of ["system", "stream", "temperature", "top_p", "top_k", "stop_sequences", "tool_choice"]) {
		if (body[key] !== undefined) out[key] = body[key];
	}
	if (Array.isArray(out.system)) out.system = (out.system as Block[]).map(plainCache);
	if (tools.length > 0) out.tools = tools;
	else delete out.tool_choice;
	const thinking = body.thinking as Json | undefined;
	if (thinking && typeof thinking === "object") {
		const { display: _display, ...rest } = thinking;
		out.thinking = rest;
	}
	const sentEffort = (body.output_config as Json | undefined)?.effort;
	const finalEffort = effort ?? sentEffort;
	if (typeof finalEffort === "string") out.output_config = { effort: finalEffort };
	return out;
}

export type Usage = { input: number; output: number; cacheRead: number };

/** SSE 응답 변환: thinking 서명에 태그를 달고, 보고 모델명을 요청한 Claude ID로 돌린다. 사용량을 모은다. */
export class StreamRewriter {
	usage: Usage = { input: 0, output: 0, cacheRead: 0 };
	#buffer = "";
	#tagged = new Map<number, boolean>();
	#thinking = new Set<number>();
	readonly #tag: string;
	constructor(
		provider: string,
		private readonly requestedModel: string,
	) {
		this.#tag = tagOf(provider);
	}

	/** 받은 조각을 넣으면 내보낼 텍스트를 돌려준다(완성된 이벤트만). */
	push(chunk: string): string {
		this.#buffer += chunk;
		let out = "";
		let cut = this.#buffer.indexOf("\n\n");
		while (cut !== -1) {
			out += this.#event(this.#buffer.slice(0, cut));
			this.#buffer = this.#buffer.slice(cut + 2);
			cut = this.#buffer.indexOf("\n\n");
		}
		return out;
	}

	flush(): string {
		const rest = this.#buffer;
		this.#buffer = "";
		return rest.trim() ? this.#event(rest) : rest;
	}

	#event(raw: string): string {
		const lines = raw.split("\n");
		const dataAt = lines.findIndex((line) => line.startsWith("data:"));
		if (dataAt === -1) return `${raw}\n\n`;
		let data: Json;
		try {
			data = JSON.parse(lines[dataAt]!.slice(5).trim()) as Json;
		} catch {
			return `${raw}\n\n`;
		}
		const extra: string[] = [];
		const index = typeof data.index === "number" ? data.index : -1;
		switch (data.type) {
			case "message_start": {
				const message = data.message as Json | undefined;
				if (message) {
					message.model = this.requestedModel;
					this.#count(message.usage as Json | undefined);
				}
				break;
			}
			case "message_delta":
				this.#count(data.usage as Json | undefined);
				break;
			case "content_block_start": {
				const block = data.content_block as Block | undefined;
				if (block?.type === "thinking") {
					this.#thinking.add(index);
					if (typeof block.signature === "string" && block.signature) {
						block.signature = this.#tag + block.signature;
						this.#tagged.set(index, true);
					}
				}
				break;
			}
			case "content_block_delta": {
				const delta = data.delta as Json | undefined;
				if (delta?.type === "signature_delta" && !this.#tagged.get(index)) {
					delta.signature = this.#tag + String(delta.signature ?? "");
					this.#tagged.set(index, true);
				}
				break;
			}
			case "content_block_stop":
				if (this.#thinking.has(index) && !this.#tagged.get(index)) {
					this.#tagged.set(index, true);
					extra.push(
						`event: content_block_delta\ndata: ${JSON.stringify({
							type: "content_block_delta",
							index,
							delta: { type: "signature_delta", signature: this.#tag },
						})}\n\n`,
					);
				}
				break;
		}
		lines[dataAt] = `data: ${JSON.stringify(data)}`;
		return `${extra.join("")}${lines.join("\n")}\n\n`;
	}

	#count(usage: Json | undefined) {
		if (!usage) return;
		// message_start와 message_delta는 누적값을 준다: 큰 쪽을 남긴다.
		const num = (key: string) => (typeof usage[key] === "number" ? (usage[key] as number) : 0);
		this.usage.input = Math.max(this.usage.input, num("input_tokens"));
		this.usage.output = Math.max(this.usage.output, num("output_tokens"));
		this.usage.cacheRead = Math.max(this.usage.cacheRead, num("cache_read_input_tokens"));
	}
}

/** 스트리밍이 아닌 응답 본문 변환. */
export function rewriteJson(body: Json, provider: string, requestedModel: string): { body: Json; usage: Usage } {
	const tag = tagOf(provider);
	const content = Array.isArray(body.content)
		? (body.content as Block[]).map((block) =>
				block.type === "thinking" ? { ...block, signature: tag + String(block.signature ?? "") } : block,
			)
		: body.content;
	const usage = (body.usage as Json | undefined) ?? {};
	const num = (key: string) => (typeof usage[key] === "number" ? (usage[key] as number) : 0);
	return {
		body: { ...body, model: requestedModel, content },
		usage: { input: num("input_tokens"), output: num("output_tokens"), cacheRead: num("cache_read_input_tokens") },
	};
}

/** Anthropic 직행 응답의 사용량만 읽는다(바이트는 손대지 않는다). SSE면 `push`, JSON이면 `json`. */
export class UsageTap {
	usage: Usage = { input: 0, output: 0, cacheRead: 0 };
	#buffer = "";

	push(chunk: string) {
		this.#buffer += chunk;
		let cut = this.#buffer.indexOf("\n\n");
		while (cut !== -1) {
			this.#event(this.#buffer.slice(0, cut));
			this.#buffer = this.#buffer.slice(cut + 2);
			cut = this.#buffer.indexOf("\n\n");
		}
	}

	flush() {
		if (this.#buffer.trim()) this.#event(this.#buffer);
		this.#buffer = "";
	}

	json(body: unknown) {
		if (body && typeof body === "object") this.#count((body as Json).usage as Json | undefined);
	}

	#event(raw: string) {
		const line = raw.split("\n").find((entry) => entry.startsWith("data:"));
		if (!line || !line.includes('"usage"')) return;
		try {
			const data = JSON.parse(line.slice(5).trim()) as Json;
			if (data.type === "message_start") this.#count((data.message as Json | undefined)?.usage as Json | undefined);
			else if (data.type === "message_delta") this.#count(data.usage as Json | undefined);
		} catch {
			// 깨진 이벤트는 세지 않는다.
		}
	}

	#count(usage: Json | undefined) {
		if (!usage) return;
		const num = (key: string) => (typeof usage[key] === "number" ? (usage[key] as number) : 0);
		this.usage.input = Math.max(this.usage.input, num("input_tokens"));
		this.usage.output = Math.max(this.usage.output, num("output_tokens"));
		this.usage.cacheRead = Math.max(this.usage.cacheRead, num("cache_read_input_tokens"));
	}
}

# cc-proxy

Local Anthropic proxy for Claude Code: model aliases (haiku/sonnet/opus/fable) go to other providers'
Anthropic-compatible endpoints with fallbacks, ending at Claude. Guide and measured facts:
`~/chat/docs/agent/261111-claude-code-proxy-opencode-go-xai.md`.

- Pure logic lives in `config.ts`, `normalize.ts`, `stats.ts` (`bun test`); `server.ts` is I/O.
- One request transform for every non-Anthropic provider (strictest wins); provider differences are only
  URL, auth and extra headers in `upstreams.ts`. Do not branch routing on a provider name.
- Credentials come from pi's `~/.pi/agent/auth.json`; OAuth refresh takes pi's `auth.json.lock`.
- Consumers: Claude Code plugin `~/.agents/plugins/proxy`, dashboard `apps/server/src/cc_proxy.rs` +
  `apps/client/src/lib/settings/cc-proxy-section.svelte`. Keep `/_proxy/*` shapes in step with them.
- After a change: `bun test`, `bunx tsc -p .`, `systemctl --user restart cc-proxy`, then
  `claude -p "say: pong" --model haiku </dev/null` and `cc-proxy status`.
====CONFIG
/**
 * cc-proxy 설정 — `~/.config/cc-proxy/config.json`.
 *
 * Claude Code 별칭(haiku/sonnet/opus/fable)마다 프록시 대상 체인을 둔다. 체인 앞에서부터 시도하고,
 * 모두 실패하면 원래 Claude 모델(Anthropic 직행)로 간다. 체인이 비면 그 별칭은 그대로 Anthropic이다.
 * `enabled: false`면 모든 요청이 그대로 Anthropic으로 간다(Claude Code는 세션 중에도 프록시를 거친다).
 */
import { existsSync, mkdirSync, readFileSync, renameSync, statSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { homedir } from "node:os";

export const ALIASES = ["haiku", "sonnet", "opus", "fable"] as const;
export type Alias = (typeof ALIASES)[number];
export const EFFORTS = ["low", "medium", "high", "xhigh", "max"] as const;
export type Effort = (typeof EFFORTS)[number];

/** 체인 한 칸: `provider/model`. `effort`가 있으면 Claude Code가 보낸 effort 대신 이 값을 보낸다. */
export type Target = { model: string; effort?: Effort };
export type Route = { chain: Target[] };
export type Config = {
	enabled: boolean;
	routes: Record<Alias, Route>;
	/** 429·5xx·연결·인증 실패 뒤 그 대상을 건너뛰는 시간. */
	cooldownSeconds: number;
};

export const PORT = Number(process.env.CC_PROXY_PORT ?? 45870);

export const DEFAULT_CONFIG: Config = {
	enabled: true,
	routes: {
		haiku: { chain: [{ model: "opencode-go/deepseek-v4.1-flash" }] },
		sonnet: { chain: [{ model: "xai/grok-4.7" }] },
		opus: { chain: [] },
		fable: { chain: [] },
	},
	cooldownSeconds: 60,
};

export function configDir(): string {
	return process.env.CC_PROXY_CONFIG_DIR ?? join(homedir(), ".config", "cc-proxy");
}

/** Claude 모델 ID(`claude-haiku-5-5`, `claude-opus-5-5[1m]`)의 별칭. Claude가 아니면 null. */
export function aliasOf(model: unknown): Alias | null {
	if (typeof model !== "string") return null;
	const match = /^claude-(haiku|sonnet|opus|fable)\b/.exec(model.toLowerCase());
	return (match?.[1] as Alias | undefined) ?? null;
}

/** `provider/model` → 둘로. 형식이 틀리면 null. */
export function splitTarget(model: string): { provider: string; id: string } | null {
	const slash = model.indexOf("/");
	if (slash <= 0 || slash === model.length - 1) return null;
	return { provider: model.slice(0, slash), id: model.slice(slash + 1) };
}

/** 검증하고 빠진 칸은 기본값으로 채운다. 틀리면 이유를 던진다. */
export function validate(input: unknown, providers: readonly string[]): Config {
	if (!input || typeof input !== "object") throw new Error("config must be an object");
	const raw = input as Partial<Config> & { routes?: Partial<Record<string, Partial<Route>>> };
	const routes = {} as Record<Alias, Route>;
	for (const alias of ALIASES) {
		const chain = raw.routes?.[alias]?.chain ?? DEFAULT_CONFIG.routes[alias].chain;
		if (!Array.isArray(chain)) throw new Error(`${alias}: chain must be a list`);
		if (chain.length > 8) throw new Error(`${alias}: at most 8 targets`);
		const seen = new Set<string>();
		routes[alias] = {
			chain: chain.map((target) => {
				if (!target || typeof target.model !== "string") throw new Error(`${alias}: target needs a model`);
				const split = splitTarget(target.model);
				if (!split) throw new Error(`${alias}: ${target.model} is not provider/model`);
				if (!providers.includes(split.provider)) {
					throw new Error(`${alias}: provider ${split.provider} is not supported (${providers.join(", ")})`);
				}
				if (seen.has(target.model)) throw new Error(`${alias}: ${target.model} is listed twice`);
				seen.add(target.model);
				if (target.effort !== undefined && !EFFORTS.includes(target.effort)) {
					throw new Error(`${alias}: effort is ${EFFORTS.join("/")}`);
				}
				return target.effort ? { model: target.model, effort: target.effort } : { model: target.model };
			}),
		};
	}
	const cooldownSeconds = raw.cooldownSeconds ?? DEFAULT_CONFIG.cooldownSeconds;
	if (!(Number.isFinite(cooldownSeconds) && cooldownSeconds >= 0 && cooldownSeconds <= 3600)) {
		throw new Error("cooldownSeconds is 0–3600");
	}
	return { enabled: raw.enabled ?? DEFAULT_CONFIG.enabled, routes, cooldownSeconds };
}

/** 파일 버전: 저장할 때 읽은 버전과 다르면(그 사이 손으로 고쳤으면) 거절한다. */
export function versionOf(path: string): string {
	try {
		const stat = statSync(path);
		return `${stat.mtimeMs}-${stat.size}`;
	} catch {
		return "missing";
	}
}

export function configPath(): string {
	return join(configDir(), "config.json");
}

export function readConfig(providers: readonly string[]): { config: Config; version: string; error?: string } {
	const path = configPath();
	const version = versionOf(path);
	if (!existsSync(path)) return { config: DEFAULT_CONFIG, version };
	try {
		return { config: validate(JSON.parse(readFileSync(path, "utf8")), providers), version };
	} catch (cause) {
		return { config: DEFAULT_CONFIG, version, error: cause instanceof Error ? cause.message : String(cause) };
	}
}

export function writeConfig(config: Config): string {
	const path = configPath();
	mkdirSync(dirname(path), { recursive: true });
	const tmp = `${path}.${process.pid}.tmp`;
	writeFileSync(tmp, `${JSON.stringify(config, null, "\t")}\n`);
	renameSync(tmp, path);
	return versionOf(path);
}
====NORMALIZE
/**
 * 요청·응답 변환 — 순수 함수만.
 *
 * Claude Code는 Anthropic 전용 beta 형태를 보낸다: 대화 중간의 `role: "system"` 메시지,
 * `tool_addition` 블록(대화 중 추가된 도구), `tool_use.caller`, `context_management`,
 * `metadata.user_id`(계정 UUID). Anthropic 호환이라도 다른 업체는 이것을 422로 거절하므로
 * (xAI 실측 261111), 다른 업체로 보낼 때는 표준 Messages 형태로 바꾼다. 업체별로 갈래를 두지 않고
 * 가장 엄격한 쪽에 맞춘 한 가지 변환을 모두에 쓴다.
 *
 * thinking 블록의 서명은 업체마다 다르고 서로 검증하지 못한다. 그래서 다른 업체가 만든 thinking의
 * 서명 앞에 `ccproxy:<provider>:`를 붙여 두고, 다음 요청에서 그 업체로 갈 때만 원래 서명으로
 * 되돌려 남기고 나머지 대상(Anthropic 포함)에게서는 그 블록을 뺀다.
 */
import type { Effort } from "./config.ts";

type Json = Record<string, unknown>;
type Block = Json & { type?: string };
type Message = { role: string; content: string | Block[] };

export const TAG = "ccproxy:";
const tagOf = (provider: string) => `${TAG}${provider}:`;

const KNOWN_BLOCKS = new Set(["text", "image", "document", "tool_use", "tool_result", "thinking", "redacted_thinking"]);
const TOOL_KEYS = ["name", "description", "input_schema"] as const;

/** 엄격한 백엔드가 거절하는 키워드. 인자 검증은 Claude Code의 도구가 실행할 때 다시 한다. */
const DROPPED_SCHEMA_KEYS = new Set(["$schema", "pattern", "patternProperties", "propertyNames"]);

/**
 * JSON Schema를 가장 엄격한 업체에 맞춘다(261111 실측):
 * - null 값 키를 지운다. `properties`가 있는 객체에 `required`가 없으면 `[]`를 채운다
 *   (xAI는 빠진 `required`를 null로 읽어 422).
 * - `pattern`(제어 문자 `\0` 포함)·`propertyNames`·`$schema`를 지우고 `const`는 `enum`으로 바꾼다
 *   (OpenCode Go deepseek은 요청을 나눠 받는 백엔드 일부가 "invalid JSON Schema"로 400).
 * 스키마 자체가 아닌 곳(`properties`의 이름들, `enum` 값)은 키워드로 보지 않는다.
 */
export function strictSchema(value: unknown): unknown {
	if (Array.isArray(value)) return value.map(strictSchema);
	if (!value || typeof value !== "object") return value;
	const out: Json = {};
	for (const [key, inner] of Object.entries(value)) {
		if (inner === null || DROPPED_SCHEMA_KEYS.has(key)) continue;
		if (key === "const") out.enum = [inner];
		else if ((key === "properties" || key === "$defs" || key === "definitions") && typeof inner === "object") {
			out[key] = Object.fromEntries(Object.entries(inner as Json).map(([name, schema]) => [name, strictSchema(schema)]));
		} else if (key === "enum" || key === "default" || key === "examples" || key === "required") out[key] = inner;
		else out[key] = strictSchema(inner);
	}
	if (out.properties && typeof out.properties === "object" && !Array.isArray(out.required)) out.required = [];
	return out;
}

function blocks(content: Message["content"]): Block[] {
	return typeof content === "string" ? [{ type: "text", text: content }] : content;
}

/** cache_control은 남기되 Anthropic 전용 `ttl`은 뺀다. */
function plainCache(block: Block): Block {
	const out: Block = { ...block };
	const cache = out.cache_control as Json | undefined;
	if (cache && typeof cache === "object") out.cache_control = { type: "ephemeral" };
	return out;
}

/** 이 대상(`native`면 Anthropic)이 받을 thinking 블록만 남긴다. */
export function keepThinking(block: Block, target: string | "native"): Block | null {
	if (block.type === "redacted_thinking") return target === "native" ? block : null;
	if (block.type !== "thinking") return block;
	const signature = typeof block.signature === "string" ? block.signature : "";
	if (target === "native") return signature.startsWith(TAG) ? null : block;
	const tag = tagOf(target);
	if (!signature.startsWith(tag)) return null;
	return { ...block, signature: signature.slice(tag.length) };
}

/** 같은 역할이 이어지면 한 메시지로 합친다(블록을 지우고 나면 생길 수 있다). 빈 메시지는 뺀다. */
function mergeRuns(messages: Message[]): Message[] {
	const out: Message[] = [];
	for (const message of messages) {
		const content = blocks(message.content);
		if (content.length === 0) continue;
		const last = out.at(-1);
		if (last && last.role === message.role) last.content = [...blocks(last.content), ...content];
		else out.push({ role: message.role, content: [...content] });
	}
	return out;
}

/** Anthropic 직행 요청: 다른 업체가 만든 thinking 블록만 뺀다. 나머지는 손대지 않는다. */
export function forNative(body: Json): Json {
	const messages = body.messages as Message[] | undefined;
	if (!Array.isArray(messages)) return body;
	let touched = false;
	const next = messages.map((message) => {
		if (typeof message.content === "string") return message;
		const content = message.content.map((block) => keepThinking(block, "native")).filter((b): b is Block => b !== null);
		if (content.length !== message.content.length) touched = true;
		return { ...message, content };
	});
	return touched ? { ...body, messages: mergeRuns(next) } : body;
}

/** 다른 업체용 표준 Messages 요청. `provider`는 thinking 서명 태그, `model`은 업체 쪽 ID. */
export function forForeign(body: Json, provider: string, model: string, effort?: Effort): Json {
	const tools: Block[] = [];
	const toolNames = new Set<string>();
	const addTool = (tool: unknown) => {
		if (!tool || typeof tool !== "object") return;
		const source = tool as Json;
		// 서버 도구(web_search 등 type이 있는 것)는 그 업체에 없다.
		if (typeof source.type === "string" && source.type !== "custom") return;
		if (typeof source.name !== "string" || toolNames.has(source.name)) return;
		toolNames.add(source.name);
		const out: Block = {};
		for (const key of TOOL_KEYS) if (source[key] !== undefined) out[key] = source[key];
		out.input_schema = out.input_schema ? strictSchema(out.input_schema) : { type: "object", properties: {} };
		tools.push(out);
	};
	for (const tool of (body.tools as unknown[] | undefined) ?? []) addTool(tool);

	// 대화 중간 system 메시지: 텍스트는 앞(없으면 다음) user 메시지 끝에 붙인다.
	const messages: Message[] = [];
	let pending: Block[] = [];
	for (const message of (body.messages as Message[] | undefined) ?? []) {
		const content: Block[] = [];
		for (const raw of blocks(message.content)) {
			if (raw.type === "tool_addition") {
				addTool(raw.tool);
				continue;
			}
			const block = keepThinking(raw, provider);
			if (!block || !KNOWN_BLOCKS.has(String(block.type))) continue;
			const clean = plainCache(block);
			if (clean.type === "tool_use") delete clean.caller;
			if (clean.type === "thinking") delete clean.display;
			if (clean.type === "tool_result" && Array.isArray(clean.content)) {
				clean.content = (clean.content as Block[])
					.filter((part) => part.type === "text" || part.type === "image")
					.map(plainCache);
			}
			content.push(clean);
		}
		if (message.role === "system") {
			const text = content.filter((block) => block.type === "text");
			const previous = messages.at(-1);
			if (previous?.role === "user") previous.content = [...blocks(previous.content), ...text];
			else pending.push(...text);
			continue;
		}
		if (message.role === "user" && pending.length > 0) {
			content.push(...pending);
			pending = [];
		}
		messages.push({ role: message.role, content });
	}
	if (pending.length > 0) messages.push({ role: "user", content: pending });

	const out: Json = { model, messages: mergeRuns(messages), max_tokens: body.max_tokens ?? 32000 };
	for (const key of ["system", "stream", "temperature", "top_p", "top_k", "stop_sequences", "tool_choice"]) {
		if (body[key] !== undefined) out[key] = body[key];
	}
	if (Array.isArray(out.system)) out.system = (out.system as Block[]).map(plainCache);
	if (tools.length > 0) out.tools = tools;
	else delete out.tool_choice;
	const thinking = body.thinking as Json | undefined;
	if (thinking && typeof thinking === "object") {
		const { display: _display, ...rest } = thinking;
		out.thinking = rest;
	}
	const sentEffort = (body.output_config as Json | undefined)?.effort;
	const finalEffort = effort ?? sentEffort;
	if (typeof finalEffort === "string") out.output_config = { effort: finalEffort };
	return out;
}

export type Usage = { input: number; output: number; cacheRead: number };

/** SSE 응답 변환: thinking 서명에 태그를 달고, 보고 모델명을 요청한 Claude ID로 돌린다. 사용량을 모은다. */
export class StreamRewriter {
	usage: Usage = { input: 0, output: 0, cacheRead: 0 };
	#buffer = "";
	#tagged = new Map<number, boolean>();
	#thinking = new Set<number>();
	readonly #tag: string;
	constructor(
		provider: string,
		private readonly requestedModel: string,
	) {
		this.#tag = tagOf(provider);
	}

	/** 받은 조각을 넣으면 내보낼 텍스트를 돌려준다(완성된 이벤트만). */
	push(chunk: string): string {
		this.#buffer += chunk;
		let out = "";
		let cut = this.#buffer.indexOf("\n\n");
		while (cut !== -1) {
			out += this.#event(this.#buffer.slice(0, cut));
			this.#buffer = this.#buffer.slice(cut + 2);
			cut = this.#buffer.indexOf("\n\n");
		}
		return out;
	}

	flush(): string {
		const rest = this.#buffer;
		this.#buffer = "";
		return rest.trim() ? this.#event(rest) : rest;
	}

	#event(raw: string): string {
		const lines = raw.split("\n");
		const dataAt = lines.findIndex((line) => line.startsWith("data:"));
		if (dataAt === -1) return `${raw}\n\n`;
		let data: Json;
		try {
			data = JSON.parse(lines[dataAt]!.slice(5).trim()) as Json;
		} catch {
			return `${raw}\n\n`;
		}
		const extra: string[] = [];
		const index = typeof data.index === "number" ? data.index : -1;
		switch (data.type) {
			case "message_start": {
				const message = data.message as Json | undefined;
				if (message) {
					message.model = this.requestedModel;
					this.#count(message.usage as Json | undefined);
				}
				break;
			}
			case "message_delta":
				this.#count(data.usage as Json | undefined);
				break;
			case "content_block_start": {
				const block = data.content_block as Block | undefined;
				if (block?.type === "thinking") {
					this.#thinking.add(index);
					if (typeof block.signature === "string" && block.signature) {
						block.signature = this.#tag + block.signature;
						this.#tagged.set(index, true);
					}
				}
				break;
			}
			case "content_block_delta": {
				const delta = data.delta as Json | undefined;
				if (delta?.type === "signature_delta" && !this.#tagged.get(index)) {
					delta.signature = this.#tag + String(delta.signature ?? "");
					this.#tagged.set(index, true);
				}
				break;
			}
			case "content_block_stop":
				if (this.#thinking.has(index) && !this.#tagged.get(index)) {
					this.#tagged.set(index, true);
					extra.push(
						`event: content_block_delta\ndata: ${JSON.stringify({
							type: "content_block_delta",
							index,
							delta: { type: "signature_delta", signature: this.#tag },
						})}\n\n`,
					);
				}
				break;
		}
		lines[dataAt] = `data: ${JSON.stringify(data)}`;
		return `${extra.join("")}${lines.join("\n")}\n\n`;
	}

	#count(usage: Json | undefined) {
		if (!usage) return;
		// message_start와 message_delta는 누적값을 준다: 큰 쪽을 남긴다.
		const num = (key: string) => (typeof usage[key] === "number" ? (usage[key] as number) : 0);
		this.usage.input = Math.max(this.usage.input, num("input_tokens"));
		this.usage.output = Math.max(this.usage.output, num("output_tokens"));
		this.usage.cacheRead = Math.max(this.usage.cacheRead, num("cache_read_input_tokens"));
	}
}

/** 스트리밍이 아닌 응답 본문 변환. */
export function rewriteJson(body: Json, provider: string, requestedModel: string): { body: Json; usage: Usage } {
	const tag = tagOf(provider);
	const content = Array.isArray(body.content)
		? (body.content as Block[]).map((block) =>
				block.type === "thinking" ? { ...block, signature: tag + String(block.signature ?? "") } : block,
			)
		: body.content;
	const usage = (body.usage as Json | undefined) ?? {};
	const num = (key: string) => (typeof usage[key] === "number" ? (usage[key] as number) : 0);
	return {
		body: { ...body, model: requestedModel, content },
		usage: { input: num("input_tokens"), output: num("output_tokens"), cacheRead: num("cache_read_input_tokens") },
	};
}

/** Anthropic 직행 응답의 사용량만 읽는다(바이트는 손대지 않는다). SSE면 `push`, JSON이면 `json`. */
export class UsageTap {
	usage: Usage = { input: 0, output: 0, cacheRead: 0 };
	#buffer = "";

	push(chunk: string) {
		this.#buffer += chunk;
		let cut = this.#buffer.indexOf("\n\n");
		while (cut !== -1) {
			this.#event(this.#buffer.slice(0, cut));
			this.#buffer = this.#buffer.slice(cut + 2);
			cut = this.#buffer.indexOf("\n\n");
		}
	}

	flush() {
		if (this.#buffer.trim()) this.#event(this.#buffer);
		this.#buffer = "";
	}

	json(body: unknown) {
		if (body && typeof body === "object") this.#count((body as Json).usage as Json | undefined);
	}

	#event(raw: string) {
		const line = raw.split("\n").find((entry) => entry.startsWith("data:"));
		if (!line || !line.includes('"usage"')) return;
		try {
			const data = JSON.parse(line.slice(5).trim()) as Json;
			if (data.type === "message_start") this.#count((data.message as Json | undefined)?.usage as Json | undefined);
			else if (data.type === "message_delta") this.#count(data.usage as Json | undefined);
		} catch {
			// 깨진 이벤트는 세지 않는다.
		}
	}

	#count(usage: Json | undefined) {
		if (!usage) return;
		const num = (key: string) => (typeof usage[key] === "number" ? (usage[key] as number) : 0);
		this.usage.input = Math.max(this.usage.input, num("input_tokens"));
		this.usage.output = Math.max(this.usage.output, num("output_tokens"));
		this.usage.cacheRead = Math.max(this.usage.cacheRead, num("cache_read_input_tokens"));
	}
}

# cc-proxy

Local Anthropic proxy for Claude Code: model aliases (haiku/sonnet/opus/fable) go to other providers'
Anthropic-compatible endpoints with fallbacks, ending at Claude. Guide and measured facts:
`~/chat/docs/agent/261111-claude-code-proxy-opencode-go-xai.md`.

- Pure logic lives in `config.ts`, `normalize.ts`, `stats.ts` (`bun test`); `server.ts` is I/O.
- One request transform for every non-Anthropic provider (strictest wins); provider differences are only
  URL, auth and extra headers in `upstreams.ts`. Do not branch routing on a provider name.
- Credentials come from pi's `~/.pi/agent/auth.json`; OAuth refresh takes pi's `auth.json.lock`.
- Consumers: Claude Code plugin `~/.agents/plugins/proxy`, dashboard `apps/server/src/cc_proxy.rs` +
  `apps/client/src/lib/settings/cc-proxy-section.svelte`. Keep `/_proxy/*` shapes in step with them.
- After a change: `bun test`, `bunx tsc -p .`, `systemctl --user restart cc-proxy`, then
  `claude -p "say: pong" --model haiku </dev/null` and `cc-proxy status`.
====CONFIG
/**
 * cc-proxy 설정 — `~/.config/cc-proxy/config.json`.
 *
 * Claude Code 별칭(haiku/sonnet/opus/fable)마다 프록시 대상 체인을 둔다. 체인 앞에서부터 시도하고,
 * 모두 실패하면 원래 Claude 모델(Anthropic 직행)로 간다. 체인이 비면 그 별칭은 그대로 Anthropic이다.
 * `enabled: false`면 모든 요청이 그대로 Anthropic으로 간다(Claude Code는 세션 중에도 프록시를 거친다).
 */
import { existsSync, mkdirSync, readFileSync, renameSync, statSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { homedir } from "node:os";

export const ALIASES = ["haiku", "sonnet", "opus", "fable"] as const;
export type Alias = (typeof ALIASES)[number];
export const EFFORTS = ["low", "medium", "high", "xhigh", "max"] as const;
export type Effort = (typeof EFFORTS)[number];

/** 체인 한 칸: `provider/model`. `effort`가 있으면 Claude Code가 보낸 effort 대신 이 값을 보낸다. */
export type Target = { model: string; effort?: Effort };
export type Route = { chain: Target[] };
export type Config = {
	enabled: boolean;
	routes: Record<Alias, Route>;
	/** 429·5xx·연결·인증 실패 뒤 그 대상을 건너뛰는 시간. */
	cooldownSeconds: number;
};

export const PORT = Number(process.env.CC_PROXY_PORT ?? 45870);

export const DEFAULT_CONFIG: Config = {
	enabled: true,
	routes: {
		haiku: { chain: [{ model: "opencode-go/deepseek-v4.1-flash" }] },
		sonnet: { chain: [{ model: "xai/grok-4.7" }] },
		opus: { chain: [] },
		fable: { chain: [] },
	},
	cooldownSeconds: 60,
};

export function configDir(): string {
	return process.env.CC_PROXY_CONFIG_DIR ?? join(homedir(), ".config", "cc-proxy");
}

/** Claude 모델 ID(`claude-haiku-5-5`, `claude-opus-5-5[1m]`)의 별칭. Claude가 아니면 null. */
export function aliasOf(model: unknown): Alias | null {
	if (typeof model !== "string") return null;
	const match = /^claude-(haiku|sonnet|opus|fable)\b/.exec(model.toLowerCase());
	return (match?.[1] as Alias | undefined) ?? null;
}

/** `provider/model` → 둘로. 형식이 틀리면 null. */
export function splitTarget(model: string): { provider: string; id: string } | null {
	const slash = model.indexOf("/");
	if (slash <= 0 || slash === model.length - 1) return null;
	return { provider: model.slice(0, slash), id: model.slice(slash + 1) };
}

/** 검증하고 빠진 칸은 기본값으로 채운다. 틀리면 이유를 던진다. */
export function validate(input: unknown, providers: readonly string[]): Config {
	if (!input || typeof input !== "object") throw new Error("config must be an object");
	const raw = input as Partial<Config> & { routes?: Partial<Record<string, Partial<Route>>> };
	const routes = {} as Record<Alias, Route>;
	for (const alias of ALIASES) {
		const chain = raw.routes?.[alias]?.chain ?? DEFAULT_CONFIG.routes[alias].chain;
		if (!Array.isArray(chain)) throw new Error(`${alias}: chain must be a list`);
		if (chain.length > 8) throw new Error(`${alias}: at most 8 targets`);
		const seen = new Set<string>();
		routes[alias] = {
			chain: chain.map((target) => {
				if (!target || typeof target.model !== "string") throw new Error(`${alias}: target needs a model`);
				const split = splitTarget(target.model);
				if (!split) throw new Error(`${alias}: ${target.model} is not provider/model`);
				if (!providers.includes(split.provider)) {
					throw new Error(`${alias}: provider ${split.provider} is not supported (${providers.join(", ")})`);
				}
				if (seen.has(target.model)) throw new Error(`${alias}: ${target.model} is listed twice`);
				seen.add(target.model);
				if (target.effort !== undefined && !EFFORTS.includes(target.effort)) {
					throw new Error(`${alias}: effort is ${EFFORTS.join("/")}`);
				}
				return target.effort ? { model: target.model, effort: target.effort } : { model: target.model };
			}),
		};
	}
	const cooldownSeconds = raw.cooldownSeconds ?? DEFAULT_CONFIG.cooldownSeconds;
	if (!(Number.isFinite(cooldownSeconds) && cooldownSeconds >= 0 && cooldownSeconds <= 3600)) {
		throw new Error("cooldownSeconds is 0–3600");
	}
	return { enabled: raw.enabled ?? DEFAULT_CONFIG.enabled, routes, cooldownSeconds };
}

/** 파일 버전: 저장할 때 읽은 버전과 다르면(그 사이 손으로 고쳤으면) 거절한다. */
export function versionOf(path: string): string {
	try {
		const stat = statSync(path);
		return `${stat.mtimeMs}-${stat.size}`;
	} catch {
		return "missing";
	}
}

export function configPath(): string {
	return join(configDir(), "config.json");
}

export function readConfig(providers: readonly string[]): { config: Config; version: string; error?: string } {
	const path = configPath();
	const version = versionOf(path);
	if (!existsSync(path)) return { config: DEFAULT_CONFIG, version };
	try {
		return { config: validate(JSON.parse(readFileSync(path, "utf8")), providers), version };
	} catch (cause) {
		return { config: DEFAULT_CONFIG, version, error: cause instanceof Error ? cause.message : String(cause) };
	}
}

export function writeConfig(config: Config): string {
	const path = configPath();
	mkdirSync(dirname(path), { recursive: true });
	const tmp = `${path}.${process.pid}.tmp`;
	writeFileSync(tmp, `${JSON.stringify(config, null, "\t")}\n`);
	renameSync(tmp, path);
	return versionOf(path);
}
====NORMALIZE
/**
 * 요청·응답 변환 — 순수 함수만.
 *
 * Claude Code는 Anthropic 전용 beta 형태를 보낸다: 대화 중간의 `role: "system"` 메시지,
 * `tool_addition` 블록(대화 중 추가된 도구), `tool_use.caller`, `context_management`,
 * `metadata.user_id`(계정 UUID). Anthropic 호환이라도 다른 업체는 이것을 422로 거절하므로
 * (xAI 실측 261111), 다른 업체로 보낼 때는 표준 Messages 형태로 바꾼다. 업체별로 갈래를 두지 않고
 * 가장 엄격한 쪽에 맞춘 한 가지 변환을 모두에 쓴다.
 *
 * thinking 블록의 서명은 업체마다 다르고 서로 검증하지 못한다. 그래서 다른 업체가 만든 thinking의
 * 서명 앞에 `ccproxy:<provider>:`를 붙여 두고, 다음 요청에서 그 업체로 갈 때만 원래 서명으로
 * 되돌려 남기고 나머지 대상(Anthropic 포함)에게서는 그 블록을 뺀다.
 */
import type { Effort } from "./config.ts";

type Json = Record<string, unknown>;
type Block = Json & { type?: string };
type Message = { role: string; content: string | Block[] };

export const TAG = "ccproxy:";
const tagOf = (provider: string) => `${TAG}${provider}:`;

const KNOWN_BLOCKS = new Set(["text", "image", "document", "tool_use", "tool_result", "thinking", "redacted_thinking"]);
const TOOL_KEYS = ["name", "description", "input_schema"] as const;

/** 엄격한 백엔드가 거절하는 키워드. 인자 검증은 Claude Code의 도구가 실행할 때 다시 한다. */
const DROPPED_SCHEMA_KEYS = new Set(["$schema", "pattern", "patternProperties", "propertyNames"]);

/**
 * JSON Schema를 가장 엄격한 업체에 맞춘다(261111 실측):
 * - null 값 키를 지운다. `properties`가 있는 객체에 `required`가 없으면 `[]`를 채운다
 *   (xAI는 빠진 `required`를 null로 읽어 422).
 * - `pattern`(제어 문자 `\0` 포함)·`propertyNames`·`$schema`를 지우고 `const`는 `enum`으로 바꾼다
 *   (OpenCode Go deepseek은 요청을 나눠 받는 백엔드 일부가 "invalid JSON Schema"로 400).
 * 스키마 자체가 아닌 곳(`properties`의 이름들, `enum` 값)은 키워드로 보지 않는다.
 */
export function strictSchema(value: unknown): unknown {
	if (Array.isArray(value)) return value.map(strictSchema);
	if (!value || typeof value !== "object") return value;
	const out: Json = {};
	for (const [key, inner] of Object.entries(value)) {
		if (inner === null || DROPPED_SCHEMA_KEYS.has(key)) continue;
		if (key === "const") out.enum = [inner];
		else if ((key === "properties" || key === "$defs" || key === "definitions") && typeof inner === "object") {
			out[key] = Object.fromEntries(Object.entries(inner as Json).map(([name, schema]) => [name, strictSchema(schema)]));
		} else if (key === "enum" || key === "default" || key === "examples" || key === "required") out[key] = inner;
		else out[key] = strictSchema(inner);
	}
	if (out.properties && typeof out.properties === "object" && !Array.isArray(out.required)) out.required = [];
	return out;
}

function blocks(content: Message["content"]): Block[] {
	return typeof content === "string" ? [{ type: "text", text: content }] : content;
}

/** cache_control은 남기되 Anthropic 전용 `ttl`은 뺀다. */
function plainCache(block: Block): Block {
	const out: Block = { ...block };
	const cache = out.cache_control as Json | undefined;
	if (cache && typeof cache === "object") out.cache_control = { type: "ephemeral" };
	return out;
}

/** 이 대상(`native`면 Anthropic)이 받을 thinking 블록만 남긴다. */
export function keepThinking(block: Block, target: string | "native"): Block | null {
	if (block.type === "redacted_thinking") return target === "native" ? block : null;
	if (block.type !== "thinking") return block;
	const signature = typeof block.signature === "string" ? block.signature : "";
	if (target === "native") return signature.startsWith(TAG) ? null : block;
	const tag = tagOf(target);
	if (!signature.startsWith(tag)) return null;
	return { ...block, signature: signature.slice(tag.length) };
}

/** 같은 역할이 이어지면 한 메시지로 합친다(블록을 지우고 나면 생길 수 있다). 빈 메시지는 뺀다. */
function mergeRuns(messages: Message[]): Message[] {
	const out: Message[] = [];
	for (const message of messages) {
		const content = blocks(message.content);
		if (content.length === 0) continue;
		const last = out.at(-1);
		if (last && last.role === message.role) last.content = [...blocks(last.content), ...content];
		else out.push({ role: message.role, content: [...content] });
	}
	return out;
}

/** Anthropic 직행 요청: 다른 업체가 만든 thinking 블록만 뺀다. 나머지는 손대지 않는다. */
export function forNative(body: Json): Json {
	const messages = body.messages as Message[] | undefined;
	if (!Array.isArray(messages)) return body;
	let touched = false;
	const next = messages.map((message) => {
		if (typeof message.content === "string") return message;
		const content = message.content.map((block) => keepThinking(block, "native")).filter((b): b is Block => b !== null);
		if (content.length !== message.content.length) touched = true;
		return { ...message, content };
	});
	return touched ? { ...body, messages: mergeRuns(next) } : body;
}

/** 다른 업체용 표준 Messages 요청. `provider`는 thinking 서명 태그, `model`은 업체 쪽 ID. */
export function forForeign(body: Json, provider: string, model: string, effort?: Effort): Json {
	const tools: Block[] = [];
	const toolNames = new Set<string>();
	const addTool = (tool: unknown) => {
		if (!tool || typeof tool !== "object") return;
		const source = tool as Json;
		// 서버 도구(web_search 등 type이 있는 것)는 그 업체에 없다.
		if (typeof source.type === "string" && source.type !== "custom") return;
		if (typeof source.name !== "string" || toolNames.has(source.name)) return;
		toolNames.add(source.name);
		const out: Block = {};
		for (const key of TOOL_KEYS) if (source[key] !== undefined) out[key] = source[key];
		out.input_schema = out.input_schema ? strictSchema(out.input_schema) : { type: "object", properties: {} };
		tools.push(out);
	};
	for (const tool of (body.tools as unknown[] | undefined) ?? []) addTool(tool);

	// 대화 중간 system 메시지: 텍스트는 앞(없으면 다음) user 메시지 끝에 붙인다.
	const messages: Message[] = [];
	let pending: Block[] = [];
	for (const message of (body.messages as Message[] | undefined) ?? []) {
		const content: Block[] = [];
		for (const raw of blocks(message.content)) {
			if (raw.type === "tool_addition") {
				addTool(raw.tool);
				continue;
			}
			const block = keepThinking(raw, provider);
			if (!block || !KNOWN_BLOCKS.has(String(block.type))) continue;
			const clean = plainCache(block);
			if (clean.type === "tool_use") delete clean.caller;
			if (clean.type === "thinking") delete clean.display;
			if (clean.type === "tool_result" && Array.isArray(clean.content)) {
				clean.content = (clean.content as Block[])
					.filter((part) => part.type === "text" || part.type === "image")
					.map(plainCache);
			}
			content.push(clean);
		}
		if (message.role === "system") {
			const text = content.filter((block) => block.type === "text");
			const previous = messages.at(-1);
			if (previous?.role === "user") previous.content = [...blocks(previous.content), ...text];
			else pending.push(...text);
			continue;
		}
		if (message.role === "user" && pending.length > 0) {
			content.push(...pending);
			pending = [];
		}
		messages.push({ role: message.role, content });
	}
	if (pending.length > 0) messages.push({ role: "user", content: pending });

	const out: Json = { model, messages: mergeRuns(messages), max_tokens: body.max_tokens ?? 32000 };
	for (const key of ["system", "stream", "temperature", "top_p", "top_k", "stop_sequences", "tool_choice"]) {
		if (body[key] !== undefined) out[key] = body[key];
	}
	if (Array.isArray(out.system)) out.system = (out.system as Block[]).map(plainCache);
	if (tools.length > 0) out.tools = tools;
	else delete out.tool_choice;
	const thinking = body.thinking as Json | undefined;
	if (thinking && typeof thinking === "object") {
		const { display: _display, ...rest } = thinking;
		out.thinking = rest;
	}
	const sentEffort = (body.output_config as Json | undefined)?.effort;
	const finalEffort = effort ?? sentEffort;
	if (typeof finalEffort === "string") out.output_config = { effort: finalEffort };
	return out;
}

export type Usage = { input: number; output: number; cacheRead: number };

/** SSE 응답 변환: thinking 서명에 태그를 달고, 보고 모델명을 요청한 Claude ID로 돌린다. 사용량을 모은다. */
export class StreamRewriter {
	usage: Usage = { input: 0, output: 0, cacheRead: 0 };
	#buffer = "";
	#tagged = new Map<number, boolean>();
	#thinking = new Set<number>();
	readonly #tag: string;
	constructor(
		provider: string,
		private readonly requestedModel: string,
	) {
		this.#tag = tagOf(provider);
	}

	/** 받은 조각을 넣으면 내보낼 텍스트를 돌려준다(완성된 이벤트만). */
	push(chunk: string): string {
		this.#buffer += chunk;
		let out = "";
		let cut = this.#buffer.indexOf("\n\n");
		while (cut !== -1) {
			out += this.#event(this.#buffer.slice(0, cut));
			this.#buffer = this.#buffer.slice(cut + 2);
			cut = this.#buffer.indexOf("\n\n");
		}
		return out;
	}

	flush(): string {
		const rest = this.#buffer;
		this.#buffer = "";
		return rest.trim() ? this.#event(rest) : rest;
	}

	#event(raw: string): string {
		const lines = raw.split("\n");
		const dataAt = lines.findIndex((line) => line.startsWith("data:"));
		if (dataAt === -1) return `${raw}\n\n`;
		let data: Json;
		try {
			data = JSON.parse(lines[dataAt]!.slice(5).trim()) as Json;
		} catch {
			return `${raw}\n\n`;
		}
		const extra: string[] = [];
		const index = typeof data.index === "number" ? data.index : -1;
		switch (data.type) {
			case "message_start": {
				const message = data.message as Json | undefined;
				if (message) {
					message.model = this.requestedModel;
					this.#count(message.usage as Json | undefined);
				}
				break;
			}
			case "message_delta":
				this.#count(data.usage as Json | undefined);
				break;
			case "content_block_start": {
				const block = data.content_block as Block | undefined;
				if (block?.type === "thinking") {
					this.#thinking.add(index);
					if (typeof block.signature === "string" && block.signature) {
						block.signature = this.#tag + block.signature;
						this.#tagged.set(index, true);
					}
				}
				break;
			}
			case "content_block_delta": {
				const delta = data.delta as Json | undefined;
				if (delta?.type === "signature_delta" && !this.#tagged.get(index)) {
					delta.signature = this.#tag + String(delta.signature ?? "");
					this.#tagged.set(index, true);
				}
				break;
			}
			case "content_block_stop":
				if (this.#thinking.has(index) && !this.#tagged.get(index)) {
					this.#tagged.set(index, true);
					extra.push(
						`event: content_block_delta\ndata: ${JSON.stringify({
							type: "content_block_delta",
							index,
							delta: { type: "signature_delta", signature: this.#tag },
						})}\n\n`,
					);
				}
				break;
		}
		lines[dataAt] = `data: ${JSON.stringify(data)}`;
		return `${extra.join("")}${lines.join("\n")}\n\n`;
	}

	#count(usage: Json | undefined) {
		if (!usage) return;
		// message_start와 message_delta는 누적값을 준다: 큰 쪽을 남긴다.
		const num = (key: string) => (typeof usage[key] === "number" ? (usage[key] as number) : 0);
		this.usage.input = Math.max(this.usage.input, num("input_tokens"));
		this.usage.output = Math.max(this.usage.output, num("output_tokens"));
		this.usage.cacheRead = Math.max(this.usage.cacheRead, num("cache_read_input_tokens"));
	}
}

/** 스트리밍이 아닌 응답 본문 변환. */
export function rewriteJson(body: Json, provider: string, requestedModel: string): { body: Json; usage: Usage } {
	const tag = tagOf(provider);
	const content = Array.isArray(body.content)
		? (body.content as Block[]).map((block) =>
				block.type === "thinking" ? { ...block, signature: tag + String(block.signature ?? "") } : block,
			)
		: body.content;
	const usage = (body.usage as Json | undefined) ?? {};
	const num = (key: string) => (typeof usage[key] === "number" ? (usage[key] as number) : 0);
	return {
		body: { ...body, model: requestedModel, content },
		usage: { input: num("input_tokens"), output: num("output_tokens"), cacheRead: num("cache_read_input_tokens") },
	};
}

/** Anthropic 직행 응답의 사용량만 읽는다(바이트는 손대지 않는다). SSE면 `push`, JSON이면 `json`. */
export class UsageTap {
	usage: Usage = { input: 0, output: 0, cacheRead: 0 };
	#buffer = "";

	push(chunk: string) {
		this.#buffer += chunk;
		let cut = this.#buffer.indexOf("\n\n");
		while (cut !== -1) {
			this.#event(this.#buffer.slice(0, cut));
			this.#buffer = this.#buffer.slice(cut + 2);
			cut = this.#buffer.indexOf("\n\n");
		}
	}

	flush() {
		if (this.#buffer.trim()) this.#event(this.#buffer);
		this.#buffer = "";
	}

	json(body: unknown) {
		if (body && typeof body === "object") this.#count((body as Json).usage as Json | undefined);
	}

	#event(raw: string) {
		const line = raw.split("\n").find((entry) => entry.startsWith("data:"));
		if (!line || !line.includes('"usage"')) return;
		try {
			const data = JSON.parse(line.slice(5).trim()) as Json;
			if (data.type === "message_start") this.#count((data.message as Json | undefined)?.usage as Json | undefined);
			else if (data.type === "message_delta") this.#count(data.usage as Json | undefined);
		} catch {
			// 깨진 이벤트는 세지 않는다.
		}
	}

	#count(usage: Json | undefined) {
		if (!usage) return;
		const num = (key: string) => (typeof usage[key] === "number" ? (usage[key] as number) : 0);
		this.usage.input = Math.max(this.usage.input, num("input_tokens"));
		this.usage.output = Math.max(this.usage.output, num("output_tokens"));
		this.usage.cacheRead = Math.max(this.usage.cacheRead, num("cache_read_input_tokens"));
	}
}

/**
 * cc-proxy 서버 — Claude Code의 `ANTHROPIC_BASE_URL` 자리에 선다.
 *
 * `POST /v1/messages`만 들여다본다: 모델 ID의 별칭(haiku/sonnet/…)에 체인이 있고 프록시가 켜져 있으면
 * 체인 앞부터 그 업체로 보내고(요청은 `forForeign`으로 표준화), 실패(2xx 아님, 연결, 첫 바이트 시간 초과)면
 * 다음 대상, 모두 실패하면 원래 요청을 Anthropic으로 보낸다. 그 밖의 경로(count_tokens, OAuth, 모델 목록 …)는
 * 바이트 그대로 Anthropic으로 넘긴다. Claude Code의 OAuth 헤더는 Anthropic으로만 가고 다른 업체로는
 * 가지 않는다; 다른 업체에는 pi의 키를 붙인다.
 *
 * `/_proxy/*`는 관리용: health, stats, config, enabled.
 */
import { randomUUID } from "node:crypto";
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import {
	aliasOf,
	type Config,
	PORT,
	readConfig,
	splitTarget,
	type Target,
	validate,
	versionOf,
	configPath,
	writeConfig,
} from "./config.ts";
import { forForeign, forNative, rewriteJson, StreamRewriter, UsageTap } from "./normalize.ts";
import * as statsStore from "./stats.ts";
import { credentialFor, loggedIn, PROVIDER_NAMES, PROVIDERS } from "./upstreams.ts";

const ANTHROPIC = process.env.CC_PROXY_ANTHROPIC_URL ?? "https://api.anthropic.com";
/** 다른 업체가 응답 헤더를 줄 때까지 기다리는 시간. 그 뒤 스트림은 끝까지 기다린다. */
const FIRST_BYTE_MS = Number(process.env.CC_PROXY_FIRST_BYTE_MS ?? 90_000);
const PROCESS_SESSION = randomUUID();

const stats = statsStore.load();
let dirty = false;
const saver = setInterval(() => {
	if (!dirty) return;
	dirty = false;
	try {
		statsStore.save(stats);
	} catch (cause) {
		console.error("stats save failed", cause);
	}
}, 3000);
saver.unref?.();

/** 대상 → 쿨다운 끝 시각. */
const cooldowns = new Map<string, number>();

function currentConfig(): Config {
	const { config, error } = readConfig(PROVIDER_NAMES);
	if (error) console.error(`config.json invalid, using defaults: ${error}`);
	return config;
}

const json = (body: unknown, status = 200) =>
	new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json" } });

/** Anthropic으로 그대로(필요하면 본문만 바꿔서). */
async function toAnthropic(req: Request, url: URL, body?: string): Promise<Response> {
	const headers = new Headers(req.headers);
	headers.delete("host");
	headers.delete("content-length");
	headers.delete("accept-encoding");
	const upstream = await fetch(ANTHROPIC + url.pathname + url.search, {
		method: req.method,
		headers,
		body: body ?? (req.method === "GET" || req.method === "HEAD" ? undefined : await req.arrayBuffer()),
		signal: req.signal,
		redirect: "manual",
	});
	const out = new Headers(upstream.headers);
	out.delete("content-encoding");
	out.delete("content-length");
	return new Response(upstream.body, { status: upstream.status, headers: out });
}

function keepFailed(target: string, payload: string) {
	try {
		const dir = join(dirname(statsStore.statsPath()), "failed");
		mkdirSync(dir, { recursive: true });
		writeFileSync(join(dir, `${target.replace(/[^\w.-]+/g, "_")}.json`), payload, { mode: 0o600 });
	} catch {
		// 진단용일 뿐이다.
	}
}

type Attempt ={ response: Response; target: string } | { failed: string };

const cools = (status: number | string) => typeof status === "string" || status === 401 || status === 403 || status === 429 || status >= 500;

async function toForeign(
	req: Request,
	body: Record<string, unknown>,
	target: Target,
	session: string,
	config: Config,
	onDone: (usage: statsStore.Outcome["usage"]) => void,
): Promise<Attempt> {
	const split = splitTarget(target.model)!;
	const provider = PROVIDERS[split.provider]!;
	const fail = (status: number | string, message: string): Attempt => {
		statsStore.recordFailure(stats, target.model, status, message);
		dirty = true;
		if (cools(status) && config.cooldownSeconds > 0) cooldowns.set(target.model, Date.now() + config.cooldownSeconds * 1000);
		console.error(`${target.model} failed (${status}): ${message.slice(0, 200)}`);
		return { failed: target.model };
	};
	const until = cooldowns.get(target.model);
	if (until && until > Date.now()) return { failed: target.model };

	let headers: Record<string, string>;
	try {
		const credential = await credentialFor(split.provider);
		headers = {
			"content-type": "application/json",
			accept: body.stream ? "text/event-stream" : "application/json",
			"anthropic-version": req.headers.get("anthropic-version") ?? "2023-06-01",
			...provider.auth(credential),
			...(provider.headers?.(session) ?? {}),
		};
	} catch (cause) {
		return fail("auth", cause instanceof Error ? cause.message : String(cause));
	}
	const requested = String(body.model);
	const payload = JSON.stringify(forForeign(body, split.provider, split.id, target.effort));
	const timer = new AbortController();
	const timeout = setTimeout(() => timer.abort(new Error("no response headers")), FIRST_BYTE_MS);
	let upstream: Response;
	try {
		upstream = await fetch(`${provider.baseUrl}/v1/messages`, {
			method: "POST",
			headers,
			body: payload,
			signal: AbortSignal.any([req.signal, timer.signal]),
		});
	} catch (cause) {
		clearTimeout(timeout);
		if (req.signal.aborted) throw cause;
		return fail("network", cause instanceof Error ? cause.message : String(cause));
	}
	clearTimeout(timeout);
	if (!upstream.ok) {
		// 요청 모양 문제(4xx)는 다시 재현해 고칠 수 있게 대상마다 마지막 하나를 남긴다(이 기기에만, 0600).
		if (upstream.status >= 400 && upstream.status < 500 && upstream.status !== 429) keepFailed(target.model, payload);
		return fail(upstream.status, await upstream.text().catch(() => ""));
	}

	const outHeaders = { "x-ccproxy-target": target.model };
	if (!body.stream || !upstream.body) {
		const parsed = rewriteJson((await upstream.json()) as Record<string, unknown>, split.provider, requested);
		onDone(parsed.usage);
		return { target: target.model, response: json(parsed.body) };
	}
	const rewriter = new StreamRewriter(split.provider, requested);
	const decoder = new TextDecoder();
	const encoder = new TextEncoder();
	const stream = upstream.body.pipeThrough(
		new TransformStream<Uint8Array, Uint8Array>({
			transform(chunk, controller) {
				const out = rewriter.push(decoder.decode(chunk, { stream: true }));
				if (out) controller.enqueue(encoder.encode(out));
			},
			flush(controller) {
				const out = rewriter.flush();
				if (out) controller.enqueue(encoder.encode(out));
				onDone(rewriter.usage);
			},
		}),
	);
	return {
		target: target.model,
		response: new Response(stream, {
			status: 200,
			headers: { "content-type": "text/event-stream", "cache-control": "no-cache", ...outHeaders },
		}),
	};
}

async function messages(req: Request, url: URL): Promise<Response> {
	const text = await req.text();
	let body: Record<string, unknown>;
	try {
		body = JSON.parse(text) as Record<string, unknown>;
	} catch {
		return toAnthropic(req, url, text);
	}
	const config = currentConfig();
	const alias = aliasOf(body.model);
	const session = req.headers.get("x-claude-code-session-id") ?? undefined;
	const chain = config.enabled && alias ? config.routes[alias].chain : [];
	const record = (outcome: Omit<statsStore.Outcome, "session" | "alias">) => {
		statsStore.record(stats, { session, alias: alias ?? "other", ...outcome });
		dirty = true;
	};

	let failed = 0;
	for (const target of chain) {
		const attempt = await toForeign(req, body, target, session ?? PROCESS_SESSION, config, (usage) =>
			record({ target: target.model, fallbacks: failed, usage }),
		);
		if ("response" in attempt) return attempt.response;
		failed += 1;
	}

	const native = forNative(body);
	const response = await toAnthropic(req, url, native === body ? text : JSON.stringify(native));
	const target = `native/${String(body.model)}`;
	const out = new Headers(response.headers);
	if (failed > 0) out.set("x-ccproxy-target", target);
	if (!response.ok || !response.body) {
		record({ target: response.ok ? target : undefined, fallbacks: failed });
		return new Response(response.body, { status: response.status, headers: out });
	}
	// 바이트는 그대로 넘기고 사용량만 읽어, 응답이 끝날 때 센다.
	const tap = new UsageTap();
	const streamed = response.headers.get("content-type")?.includes("text/event-stream") ?? false;
	const decoder = new TextDecoder();
	let whole = "";
	const body$ = response.body.pipeThrough(
		new TransformStream<Uint8Array, Uint8Array>({
			transform(chunk, controller) {
				const piece = decoder.decode(chunk, { stream: true });
				if (streamed) tap.push(piece);
				else whole += piece;
				controller.enqueue(chunk);
			},
			flush() {
				if (streamed) tap.flush();
				else {
					try {
						tap.json(JSON.parse(whole));
					} catch {
						// 사용량 없이 센다.
					}
				}
				record({ target, fallbacks: failed, usage: tap.usage });
			},
		}),
	);
	return new Response(body$, { status: response.status, headers: out });
}

function configView() {
	const { config, version, error } = readConfig(PROVIDER_NAMES);
	return {
		config,
		version,
		error,
		providers: PROVIDER_NAMES.map((name) => ({ name, loggedIn: loggedIn(name) })),
	};
}

function cooldownView() {
	const now = Date.now();
	return [...cooldowns.entries()].filter(([, until]) => until > now).map(([target, until]) => ({ target, until }));
}

async function admin(req: Request, url: URL): Promise<Response> {
	const route = `${req.method} ${url.pathname}`;
	if (req.method !== "GET" && !req.headers.get("content-type")?.includes("application/json")) {
		return json({ error: "content-type must be application/json" }, 415);
	}
	switch (route) {
		case "GET /_proxy/health":
			return json({ ok: true, enabled: currentConfig().enabled, port: PORT, pid: process.pid });
		case "GET /_proxy/stats": {
			const session = url.searchParams.get("session");
			return json({
				enabled: currentConfig().enabled,
				total: stats.total,
				day: stats.day,
				session: session ? (stats.sessions[session] ?? statsStore.emptyBucket()) : null,
				cooldowns: cooldownView(),
				recentFailures: stats.recentFailures,
			});
		}
		case "GET /_proxy/config":
			return json(configView());
		case "PUT /_proxy/config": {
			const input = (await req.json()) as { config?: unknown; version?: string };
			if (input.version !== versionOf(configPath())) {
				return json({ ...configView(), error: "config.json changed since it was read; reload" }, 409);
			}
			try {
				writeConfig(validate(input.config, PROVIDER_NAMES));
			} catch (cause) {
				return json({ error: cause instanceof Error ? cause.message : String(cause) }, 400);
			}
			return json(configView());
		}
		case "POST /_proxy/enabled": {
			const input = (await req.json()) as { enabled?: unknown };
			if (typeof input.enabled !== "boolean") return json({ error: "enabled must be true or false" }, 400);
			writeConfig({ ...currentConfig(), enabled: input.enabled });
			return json(configView());
		}
		case "POST /_proxy/reset-cooldowns":
			cooldowns.clear();
			return json({ cooldowns: [] });
	}
	return json({ error: `no route ${route}` }, 404);
}

/** 이 기기 안의 Claude Code만: 브라우저(Origin)와 DNS rebinding(Host)은 막는다. 프록시가 pi의 키를 붙이기 때문이다. */
function refuse(req: Request, url: URL): Response | null {
	if (req.headers.get("origin")) return json({ error: "browser requests are refused" }, 403);
	const host = req.headers.get("host") ?? "";
	if (!/^(127\.0\.0\.1|localhost|\[::1\])(:\d+)?$/.test(host)) return json({ error: "bad host" }, 403);
	if (url.pathname.startsWith("/v1/") && !req.headers.get("authorization") && !req.headers.get("x-api-key")) {
		return json({ type: "error", error: { type: "authentication_error", message: "cc-proxy: no Anthropic credential" } }, 401);
	}
	return null;
}

export function serve(port = PORT) {
	const server = Bun.serve({
		hostname: "127.0.0.1",
		port,
		idleTimeout: 0,
		async fetch(req) {
			const url = new URL(req.url);
			const refused = refuse(req, url);
			if (refused) return refused;
			try {
				if (url.pathname.startsWith("/_proxy/")) return await admin(req, url);
				if (req.method === "POST" && url.pathname === "/v1/messages") return await messages(req, url);
				return await toAnthropic(req, url);
			} catch (cause) {
				if (req.signal.aborted) return new Response(null, { status: 499 });
				const message = cause instanceof Error ? cause.message : String(cause);
				console.error(`${req.method} ${url.pathname}: ${message}`);
				return json({ type: "error", error: { type: "api_error", message: `cc-proxy: ${message}` } }, 502);
			}
		},
	});
	const flush = () => {
		try {
			statsStore.save(stats);
		} catch {
			// 끝나는 중이다.
		}
		process.exit(0);
	};
	process.on("SIGTERM", flush);
	process.on("SIGINT", flush);
	console.log(`cc-proxy on http://127.0.0.1:${server.port}`);
	return server;
}

/**
 * cc-proxy 서버 — Claude Code의 `ANTHROPIC_BASE_URL` 자리에 선다.
 *
 * `POST /v1/messages`만 들여다본다: 모델 ID의 별칭(haiku/sonnet/…)에 체인이 있고 프록시가 켜져 있으면
 * 체인 앞부터 그 업체로 보내고(요청은 `forForeign`으로 표준화), 실패(2xx 아님, 연결, 첫 바이트 시간 초과)면
 * 다음 대상, 모두 실패하면 원래 요청을 Anthropic으로 보낸다. 그 밖의 경로(count_tokens, OAuth, 모델 목록 …)는
 * 바이트 그대로 Anthropic으로 넘긴다. Claude Code의 OAuth 헤더는 Anthropic으로만 가고 다른 업체로는
 * 가지 않는다; 다른 업체에는 pi의 키를 붙인다.
 *
 * `/_proxy/*`는 관리용: health, stats, config, enabled.
 */
import { randomUUID } from "node:crypto";
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import {
	aliasOf,
	type Config,
	PORT,
	readConfig,
	splitTarget,
	type Target,
	validate,
	versionOf,
	configPath,
	writeConfig,
} from "./config.ts";
import { forForeign, forNative, rewriteJson, StreamRewriter, UsageTap } from "./normalize.ts";
import * as statsStore from "./stats.ts";
import { credentialFor, loggedIn, PROVIDER_NAMES, PROVIDERS } from "./upstreams.ts";

const ANTHROPIC = process.env.CC_PROXY_ANTHROPIC_URL ?? "https://api.anthropic.com";
/** 다른 업체가 응답 헤더를 줄 때까지 기다리는 시간. 그 뒤 스트림은 끝까지 기다린다. */
const FIRST_BYTE_MS = Number(process.env.CC_PROXY_FIRST_BYTE_MS ?? 90_000);
const PROCESS_SESSION = randomUUID();

const stats = statsStore.load();
let dirty = false;
const saver = setInterval(() => {
	if (!dirty) return;
	dirty = false;
	try {
		statsStore.save(stats);
	} catch (cause) {
		console.error("stats save failed", cause);
	}
}, 3000);
saver.unref?.();

/** 대상 → 쿨다운 끝 시각. */
const cooldowns = new Map<string, number>();

function currentConfig(): Config {
	const { config, error } = readConfig(PROVIDER_NAMES);
	if (error) console.error(`config.json invalid, using defaults: ${error}`);
	return config;
}

const json = (body: unknown, status = 200) =>
	new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json" } });

/** Anthropic으로 그대로(필요하면 본문만 바꿔서). */
async function toAnthropic(req: Request, url: URL, body?: string): Promise<Response> {
	const headers = new Headers(req.headers);
	headers.delete("host");
	headers.delete("content-length");
	headers.delete("accept-encoding");
	const upstream = await fetch(ANTHROPIC + url.pathname + url.search, {
		method: req.method,
		headers,
		body: body ?? (req.method === "GET" || req.method === "HEAD" ? undefined : await req.arrayBuffer()),
		signal: req.signal,
		redirect: "manual",
	});
	const out = new Headers(upstream.headers);
	out.delete("content-encoding");
	out.delete("content-length");
	return new Response(upstream.body, { status: upstream.status, headers: out });
}

function keepFailed(target: string, payload: string) {
	try {
		const dir = join(dirname(statsStore.statsPath()), "failed");
		mkdirSync(dir, { recursive: true });
		writeFileSync(join(dir, `${target.replace(/[^\w.-]+/g, "_")}.json`), payload, { mode: 0o600 });
	} catch {
		// 진단용일 뿐이다.
	}
}

type Attempt ={ response: Response; target: string } | { failed: string };

const cools = (status: number | string) => typeof status === "string" || status === 401 || status === 403 || status === 429 || status >= 500;

async function toForeign(
	req: Request,
	body: Record<string, unknown>,
	target: Target,
	session: string,
	config: Config,
	onDone: (usage: statsStore.Outcome["usage"]) => void,
): Promise<Attempt> {
	const split = splitTarget(target.model)!;
	const provider = PROVIDERS[split.provider]!;
	const fail = (status: number | string, message: string): Attempt => {
		statsStore.recordFailure(stats, target.model, status, message);
		dirty = true;
		if (cools(status) && config.cooldownSeconds > 0) cooldowns.set(target.model, Date.now() + config.cooldownSeconds * 1000);
		console.error(`${target.model} failed (${status}): ${message.slice(0, 200)}`);
		return { failed: target.model };
	};
	const until = cooldowns.get(target.model);
	if (until && until > Date.now()) return { failed: target.model };

	let headers: Record<string, string>;
	try {
		const credential = await credentialFor(split.provider);
		headers = {
			"content-type": "application/json",
			accept: body.stream ? "text/event-stream" : "application/json",
			"anthropic-version": req.headers.get("anthropic-version") ?? "2023-06-01",
			...provider.auth(credential),
			...(provider.headers?.(session) ?? {}),
		};
	} catch (cause) {
		return fail("auth", cause instanceof Error ? cause.message : String(cause));
	}
	const requested = String(body.model);
	const payload = JSON.stringify(forForeign(body, split.provider, split.id, target.effort));
	const timer = new AbortController();
	const timeout = setTimeout(() => timer.abort(new Error("no response headers")), FIRST_BYTE_MS);
	let upstream: Response;
	try {
		upstream = await fetch(`${provider.baseUrl}/v1/messages`, {
			method: "POST",
			headers,
			body: payload,
			signal: AbortSignal.any([req.signal, timer.signal]),
		});
	} catch (cause) {
		clearTimeout(timeout);
		if (req.signal.aborted) throw cause;
		return fail("network", cause instanceof Error ? cause.message : String(cause));
	}
	clearTimeout(timeout);
	if (!upstream.ok) {
		// 요청 모양 문제(4xx)는 다시 재현해 고칠 수 있게 대상마다 마지막 하나를 남긴다(이 기기에만, 0600).
		if (upstream.status >= 400 && upstream.status < 500 && upstream.status !== 429) keepFailed(target.model, payload);
		return fail(upstream.status, await upstream.text().catch(() => ""));
	}

	const outHeaders = { "x-ccproxy-target": target.model };
	if (!body.stream || !upstream.body) {
		const parsed = rewriteJson((await upstream.json()) as Record<string, unknown>, split.provider, requested);
		onDone(parsed.usage);
		return { target: target.model, response: json(parsed.body) };
	}
	const rewriter = new StreamRewriter(split.provider, requested);
	const decoder = new TextDecoder();
	const encoder = new TextEncoder();
	const stream = upstream.body.pipeThrough(
		new TransformStream<Uint8Array, Uint8Array>({
			transform(chunk, controller) {
				const out = rewriter.push(decoder.decode(chunk, { stream: true }));
				if (out) controller.enqueue(encoder.encode(out));
			},
			flush(controller) {
				const out = rewriter.flush();
				if (out) controller.enqueue(encoder.encode(out));
				onDone(rewriter.usage);
			},
		}),
	);
	return {
		target: target.model,
		response: new Response(stream, {
			status: 200,
			headers: { "content-type": "text/event-stream", "cache-control": "no-cache", ...outHeaders },
		}),
	};
}

async function messages(req: Request, url: URL): Promise<Response> {
	const text = await req.text();
	let body: Record<string, unknown>;
	try {
		body = JSON.parse(text) as Record<string, unknown>;
	} catch {
		return toAnthropic(req, url, text);
	}
	const config = currentConfig();
	const alias = aliasOf(body.model);
	const session = req.headers.get("x-claude-code-session-id") ?? undefined;
	const chain = config.enabled && alias ? config.routes[alias].chain : [];
	const record = (outcome: Omit<statsStore.Outcome, "session" | "alias">) => {
		statsStore.record(stats, { session, alias: alias ?? "other", ...outcome });
		dirty = true;
	};

	let failed = 0;
	for (const target of chain) {
		const attempt = await toForeign(req, body, target, session ?? PROCESS_SESSION, config, (usage) =>
			record({ target: target.model, fallbacks: failed, usage }),
		);
		if ("response" in attempt) return attempt.response;
		failed += 1;
	}

	const native = forNative(body);
	const response = await toAnthropic(req, url, native === body ? text : JSON.stringify(native));
	const target = `native/${String(body.model)}`;
	const out = new Headers(response.headers);
	if (failed > 0) out.set("x-ccproxy-target", target);
	if (!response.ok || !response.body) {
		record({ target: response.ok ? target : undefined, fallbacks: failed });
		return new Response(response.body, { status: response.status, headers: out });
	}
	// 바이트는 그대로 넘기고 사용량만 읽어, 응답이 끝날 때 센다.
	const tap = new UsageTap();
	const streamed = response.headers.get("content-type")?.includes("text/event-stream") ?? false;
	const decoder = new TextDecoder();
	let whole = "";
	const body$ = response.body.pipeThrough(
		new TransformStream<Uint8Array, Uint8Array>({
			transform(chunk, controller) {
				const piece = decoder.decode(chunk, { stream: true });
				if (streamed) tap.push(piece);
				else whole += piece;
				controller.enqueue(chunk);
			},
			flush() {
				if (streamed) tap.flush();
				else {
					try {
						tap.json(JSON.parse(whole));
					} catch {
						// 사용량 없이 센다.
					}
				}
				record({ target, fallbacks: failed, usage: tap.usage });
			},
		}),
	);
	return new Response(body$, { status: response.status, headers: out });
}

function configView() {
	const { config, version, error } = readConfig(PROVIDER_NAMES);
	return {
		config,
		version,
		error,
		providers: PROVIDER_NAMES.map((name) => ({ name, loggedIn: loggedIn(name) })),
	};
}

function cooldownView() {
	const now = Date.now();
	return [...cooldowns.entries()].filter(([, until]) => until > now).map(([target, until]) => ({ target, until }));
}

async function admin(req: Request, url: URL): Promise<Response> {
	const route = `${req.method} ${url.pathname}`;
	if (req.method !== "GET" && !req.headers.get("content-type")?.includes("application/json")) {
		return json({ error: "content-type must be application/json" }, 415);
	}
	switch (route) {
		case "GET /_proxy/health":
			return json({ ok: true, enabled: currentConfig().enabled, port: PORT, pid: process.pid });
		case "GET /_proxy/stats": {
			const session = url.searchParams.get("session");
			return json({
				enabled: currentConfig().enabled,
				total: stats.total,
				day: stats.day,
				session: session ? (stats.sessions[session] ?? statsStore.emptyBucket()) : null,
				cooldowns: cooldownView(),
				recentFailures: stats.recentFailures,
			});
		}
		case "GET /_proxy/config":
			return json(configView());
		case "PUT /_proxy/config": {
			const input = (await req.json()) as { config?: unknown; version?: string };
			if (input.version !== versionOf(configPath())) {
				return json({ ...configView(), error: "config.json changed since it was read; reload" }, 409);
			}
			try {
				writeConfig(validate(input.config, PROVIDER_NAMES));
			} catch (cause) {
				return json({ error: cause instanceof Error ? cause.message : String(cause) }, 400);
			}
			return json(configView());
		}
		case "POST /_proxy/enabled": {
			const input = (await req.json()) as { enabled?: unknown };
			if (typeof input.enabled !== "boolean") return json({ error: "enabled must be true or false" }, 400);
			writeConfig({ ...currentConfig(), enabled: input.enabled });
			return json(configView());
		}
		case "POST /_proxy/reset-cooldowns":
			cooldowns.clear();
			return json({ cooldowns: [] });
	}
	return json({ error: `no route ${route}` }, 404);
}

/** 이 기기 안의 Claude Code만: 브라우저(Origin)와 DNS rebinding(Host)은 막는다. 프록시가 pi의 키를 붙이기 때문이다. */
function refuse(req: Request, url: URL): Response | null {
	if (req.headers.get("origin")) return json({ error: "browser requests are refused" }, 403);
	const host = req.headers.get("host") ?? "";
	if (!/^(127\.0\.0\.1|localhost|\[::1\])(:\d+)?$/.test(host)) return json({ error: "bad host" }, 403);
	if (url.pathname.startsWith("/v1/") && !req.headers.get("authorization") && !req.headers.get("x-api-key")) {
		return json({ type: "error", error: { type: "authentication_error", message: "cc-proxy: no Anthropic credential" } }, 401);
	}
	return null;
}

export function serve(port = PORT) {
	const server = Bun.serve({
		hostname: "127.0.0.1",
		port,
		idleTimeout: 0,
		async fetch(req) {
			const url = new URL(req.url);
			const refused = refuse(req, url);
			if (refused) return refused;
			try {
				if (url.pathname.startsWith("/_proxy/")) return await admin(req, url);
				if (req.method === "POST" && url.pathname === "/v1/messages") return await messages(req, url);
				return await toAnthropic(req, url);
			} catch (cause) {
				if (req.signal.aborted) return new Response(null, { status: 499 });
				const message = cause instanceof Error ? cause.message : String(cause);
				console.error(`${req.method} ${url.pathname}: ${message}`);
				return json({ type: "error", error: { type: "api_error", message: `cc-proxy: ${message}` } }, 502);
			}
		},
	});
	const flush = () => {
		try {
			statsStore.save(stats);
		} catch {
			// 끝나는 중이다.
		}
		process.exit(0);
	};
	process.on("SIGTERM", flush);
	process.on("SIGINT", flush);
	console.log(`cc-proxy on http://127.0.0.1:${server.port}`);
	return server;
}
====UPSTREAMS
/**
 * 프록시가 보낼 수 있는 업체와 그 자격 증명.
 *
 * 키는 pi의 `~/.pi/agent/auth.json`을 그대로 쓴다(pi와 같은 계정·할당량). OAuth 토큰이 만료되면
 * pi와 같은 방식(`proper-lockfile`: `auth.json.lock` 디렉터리, 10초 지나면 stale)으로 잠그고 갱신해
 * 다시 쓴다. 회전된 refresh 토큰을 pi와 엇갈려 잃지 않기 위해서다.
 *
 * 업체 정의는 표 하나다. 라우팅 로직은 업체 이름으로 갈라지지 않고, 업체마다 다른 것은
 * 주소·인증 헤더·추가 헤더뿐이다.
 */
import { mkdirSync, readFileSync, renameSync, rmdirSync, statSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

export type Credential =
	| { type: "api_key"; key: string }
	| { type: "oauth"; access: string; refresh: string; expires: number; [extra: string]: unknown };

type OAuthRefresh = { tokenUrl: string; clientId: string };

export type Provider = {
	/** `/v1/messages`를 붙일 Anthropic 호환 주소(끝에 `/v1` 없음). */
	baseUrl: string;
	/** 자격 증명을 요청 헤더로. */
	auth: (credential: Credential) => Record<string, string>;
	/** 세션 ID가 필요한 업체의 추가 헤더. */
	headers?: (sessionId: string) => Record<string, string>;
	refresh?: OAuthRefresh;
};

const bearerOrKey = (credential: Credential): Record<string, string> =>
	credential.type === "api_key" ? { "x-api-key": credential.key } : { authorization: `Bearer ${credential.access}` };

export const PROVIDERS: Record<string, Provider> = {
	// OpenCode Go: 세션 헤더가 없으면 MissingSessionID로 거절한다(261111 실측).
	"opencode-go": {
		baseUrl: "https://opencode.ai/zen/go",
		auth: bearerOrKey,
		headers: (sessionId) => ({ "x-opencode-session": sessionId, "x-opencode-client": "claude-code" }),
	},
	// xAI: pi의 SuperGrok OAuth(device code) 토큰이 api.x.ai/v1/messages에 그대로 통한다.
	xai: {
		baseUrl: "https://api.x.ai",
		auth: bearerOrKey,
		refresh: { tokenUrl: "https://auth.x.ai/oauth2/token", clientId: "b1a00492-073a-47ea-816f-4c329264a828" },
	},
};

export const PROVIDER_NAMES = Object.keys(PROVIDERS);

export function authPath(): string {
	return process.env.CC_PROXY_AUTH_FILE ?? join(homedir(), ".pi", "agent", "auth.json");
}

let cache: { mtime: number; data: Record<string, Credential> } | null = null;

function readAuth(): Record<string, Credential> {
	const path = authPath();
	const mtime = statSync(path).mtimeMs;
	if (cache?.mtime === mtime) return cache.data;
	const data = JSON.parse(readFileSync(path, "utf8")) as Record<string, Credential>;
	cache = { mtime, data };
	return data;
}

const STALE_MS = 10_000;
const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

/** pi(`proper-lockfile`)와 같은 잠금. */
async function withAuthLock<T>(fn: () => Promise<T>): Promise<T> {
	const lock = `${authPath()}.lock`;
	for (let attempt = 0; ; attempt += 1) {
		try {
			mkdirSync(lock);
			break;
		} catch (cause) {
			if ((cause as NodeJS.ErrnoException).code !== "EEXIST") throw cause;
			try {
				if (Date.now() - statSync(lock).mtimeMs > STALE_MS) rmdirSync(lock);
			} catch {
				// 그 사이 풀렸다.
			}
			if (attempt > 100) throw new Error("auth.json is locked");
			await sleep(50);
		}
	}
	try {
		return await fn();
	} finally {
		try {
			rmdirSync(lock);
		} catch {
			// 이미 없다.
		}
	}
}

const refreshing = new Map<string, Promise<Credential>>();

async function refreshOAuth(name: string, spec: OAuthRefresh): Promise<Credential> {
	return withAuthLock(async () => {
		cache = null;
		const all = readAuth();
		const current = all[name];
		if (current?.type !== "oauth") throw new Error(`${name}: no OAuth login in pi`);
		// pi가 먼저 갱신했다.
		if (current.expires > Date.now()) return current;
		const response = await fetch(spec.tokenUrl, {
			method: "POST",
			headers: { "content-type": "application/x-www-form-urlencoded", accept: "application/json" },
			body: new URLSearchParams({ grant_type: "refresh_token", client_id: spec.clientId, refresh_token: current.refresh }),
			signal: AbortSignal.timeout(20_000),
		});
		if (!response.ok) throw new Error(`${name}: token refresh failed (${response.status}); run pi /login`);
		const body = (await response.json()) as { access_token: string; refresh_token?: string; expires_in?: number };
		const next: Credential = {
			...current,
			access: body.access_token,
			refresh: body.refresh_token ?? current.refresh,
			// pi와 같이 5분 일찍 만료로 본다.
			expires: Date.now() + (body.expires_in ?? 3600) * 1000 - 5 * 60_000,
		};
		const path = authPath();
		const tmp = `${path}.cc-proxy.tmp`;
		writeFileSync(tmp, JSON.stringify({ ...all, [name]: next }, null, 2), { mode: 0o600 });
		renameSync(tmp, path);
		cache = null;
		return next;
	});
}

/** 업체의 유효한 자격 증명. 없으면 이유를 던진다. */
export async function credentialFor(name: string): Promise<Credential> {
	const provider = PROVIDERS[name];
	if (!provider) throw new Error(`unknown provider ${name}`);
	const credential = readAuth()[name];
	if (!credential) throw new Error(`${name}: not logged in to pi`);
	if (credential.type !== "oauth" || credential.expires > Date.now()) return credential;
	if (!provider.refresh) throw new Error(`${name}: OAuth token expired`);
	let pending = refreshing.get(name);
	if (!pending) {
		pending = refreshOAuth(name, provider.refresh).finally(() => refreshing.delete(name));
		refreshing.set(name, pending);
	}
	return pending;
}

/** 이 업체에 pi 로그인이 있는가(GUI에서 고를 수 있는 업체 표시용). */
export function loggedIn(name: string): boolean {
	try {
		return Boolean(readAuth()[name]);
	} catch {
		return false;
	}
}
